    67
    68  function FormAlertWithSubmitButton({
    69      message = '',
    70      isDisabled = false,
    71      isMessageHtml = false,
    72      containerStyles,
    73      isLoading = false,
    74      onFixTheErrorsLinkPressed = () => {},
    75      enabledWhenOffline = false,
